// GIFs generated by the document renderer may be embedded, but PDFKit needs
// PNG/JPEG. Convert only a validated single-frame GIF; never fetch URLs.
const MAX_BYTES=4_194_304,MAX_PIXELS=9_000_000,MAX_IMAGES=128;
const GIF=/^data:image\/gif;base64,([a-z0-9+/\s]+={0,2})$/i;
export function validateStaticGif(bytes){
 const fail=()=>{throw Error('GIF 그림이 손상되었거나 지원하지 않는 형식입니다.');};
 if(!(bytes instanceof Uint8Array)||bytes.length<14||bytes.length>MAX_BYTES)fail();
 const header=String.fromCharCode(...bytes.slice(0,6));
 if(header!=='GIF87a'&&header!=='GIF89a')fail();
 const u16=i=>bytes[i]|bytes[i+1]<<8;
 const width=u16(6),height=u16(8);
 if(!width||!height||width*height>MAX_PIXELS)fail();
 let i=13,frames=0,ended=false;
 if(bytes[10]&128)i+=3*(1<<((bytes[10]&7)+1));
 const blocks=()=>{while(true){if(i>=bytes.length)fail();const len=bytes[i++];if(!len)return;if(i+len>bytes.length)fail();i+=len;}};
 while(i<bytes.length){
  const marker=bytes[i++];
  if(marker===0x3b){ended=true;break;}
  if(marker===0x21){if(i>=bytes.length)fail();i++;blocks();continue;}
  if(marker!==0x2c||i+9>bytes.length)fail();
  const left=u16(i),top=u16(i+2),w=u16(i+4),h=u16(i+6),packed=bytes[i+8];i+=9;
  if(!w||!h||left+w>width||top+h>height)fail();
  if(packed&128)i+=3*(1<<((packed&7)+1));
  if(i>=bytes.length)fail();i++;blocks();
  if(++frames>1)throw Error('움직이는 GIF 그림은 PDF 변환을 지원하지 않습니다.');
 }
 if(!ended||frames!==1)fail();
 return {width,height};
}
export async function normalizeGifSvg(svg,signal,{decode=globalThis.createImageBitmap,documentRef=globalThis.document}={}){
 const parser=new DOMParser(),doc=parser.parseFromString(svg,'image/svg+xml');
 if(doc.querySelector('parsererror')||doc.doctype||doc.documentElement?.localName!=='svg')throw Error('SVG 출력 형식 오류');
 const images=Array.from(doc.querySelectorAll('image'));let count=0,total=0,changed=false;
 for(const image of images){
  const refs=Array.from(image.attributes).filter(a=>(a.localName||a.name.split(':').at(-1))==='href');
  if(refs.length!==1)continue;
  const match=GIF.exec(refs[0].value.trim());if(!match)continue;
  if(signal?.aborted)throw new DOMException('PDF 변환이 취소되었습니다.','AbortError');
  if(++count>MAX_IMAGES||match[1].length>Math.ceil(MAX_BYTES*4/3)+8)throw Error('GIF 그림 처리 범위를 초과했습니다.');
  let bytes;try{const raw=atob(match[1].replace(/\s+/g,''));bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));}catch{throw Error('GIF 그림의 인코딩이 잘못되었습니다.');}
  total+=bytes.length;if(total>MAX_BYTES)throw Error('GIF 그림 처리 범위를 초과했습니다.');
  const {width,height}=validateStaticGif(bytes);
  if(typeof decode!=='function'||!documentRef?.createElement)throw Error('이 브라우저는 GIF 그림 변환을 지원하지 않습니다.');
  let bitmap,canvas;
  try{
   bitmap=await decode(new Blob([bytes],{type:'image/gif'}));
   if(signal?.aborted)throw new DOMException('PDF 변환이 취소되었습니다.','AbortError');
   if(bitmap.width!==width||bitmap.height!==height)throw Error('GIF 그림 크기가 일치하지 않습니다.');
   canvas=documentRef.createElement('canvas');canvas.width=width;canvas.height=height;
   const context=canvas.getContext('2d');if(!context)throw Error('GIF 그림을 처리할 수 없습니다.');
   context.drawImage(bitmap,0,0);refs[0].value=canvas.toDataURL('image/png');changed=true;
  }finally{bitmap?.close?.();if(canvas){canvas.width=1;canvas.height=1;}}
 }
 return changed?new XMLSerializer().serializeToString(doc.documentElement):svg;
}
